package ai.pickyour.core.conformance

import ai.pickyour.core.importing.BoundedJsonReader
import ai.pickyour.core.importing.JsonInputLimits
import ai.pickyour.core.importing.JsonInputResult
import com.fasterxml.jackson.databind.JsonNode
import java.io.InputStream

/** Fixed historical bytes and independently recorded meaning; never generated by today's writer. */
internal object LocalMigrationFixtures {
    const val VERSION = "android-local-migrations-1"
    const val BYTES = 183_586
    const val SHA256 = "f480f236e7f93e737095c7f53c3fa30ab38df1e86bc41059305b0ca11591206b"
    private val actions = setOf("read", "same-content", "edit-restore", "edit-fault", "role", "role-fault", "reject", "archive")

    fun load(): JsonNode = requireNotNull(javaClass.getResourceAsStream("/conformance/local-migrations-v1.json")).use(::load)

    fun load(input: InputStream): JsonNode {
        val bytes = input.readNBytes(BYTES + 1)
        require(bytes.size == BYTES && CrossClientFixtures.sha256(bytes) == SHA256) { "Migration fixture pin differs" }
        val parsed = BoundedJsonReader(JsonInputLimits(maxBytes = BYTES, maxStringLength = 65_536))
            .read(bytes.inputStream()) as? JsonInputResult.Parsed ?: error("Malformed pinned migration fixture")
        val root = parsed.value
        require(root["bundleVersion"].textValue() == VERSION)
        require(root["inputs"].isArray && root["inputs"].size() == 10)
        val inputs = root["inputs"].associateBy { it["id"].textValue() }
        require(inputs.size == 10)
        inputs.values.forEach { row ->
            val raw = row["payloadJSON"].textValue().toByteArray(Charsets.UTF_8)
            require(raw.size == row["bytes"].intValue() && CrossClientFixtures.sha256(raw) == row["sha256"].textValue())
        }
        require(root["cases"].isArray && root["cases"].size() == 34)
        require(root["cases"].map { it["id"].textValue() }.toSet().size == 34)
        root["cases"].forEach { row ->
            require(row["action"].textValue() in actions && row["input"].textValue() in inputs)
            require(row["checkpoint"].isNull || row["checkpoint"].textValue() in setOf("POINTER_STAGED", "POINTER_ACTIVATED"))
        }
        return root
    }
}
